#[derive(Debug, Clone, PartialEq)]
pub struct UpdateAttributes {
    pub runtime_entity_id: u64,
    pub attributes: types::PlayerAttributes,
    pub tick: u64,
}
impl UpdateAttributes {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_runtime_entity_id = (|| -> Result<_> { Ok(read_varint64(r)?) })()
            .map_err(|e| e.at("UpdateAttributes.runtime_entity_id"))?;
        let f_attributes = (|| -> Result<_> {
            Ok({
                let n = to_len(read_varint(r)?)?;
                let mut v = Vec::with_capacity(cap(n, r));
                for _ in 0..n {
                    v.push({
                        let f_min = read_lf32(r)?;
                        let f_max = read_lf32(r)?;
                        let f_current = read_lf32(r)?;
                        let f_default_min = read_lf32(r)?;
                        let f_default_max = read_lf32(r)?;
                        let f_default = read_lf32(r)?;
                        let f_name = {
                            let n = to_len(read_varint(r)?)?;
                            read_utf8(r, n)?
                        };
                        let f_modifiers = {
                            let n = to_len(read_varint(r)?)?;
                            let mut v = Vec::with_capacity(cap(n, r));
                            for _ in 0..n {
                                v.push({
                                    let f1_id = {
                                        let n = to_len(read_varint(r)?)?;
                                        read_utf8(r, n)?
                                    };
                                    let f1_name = {
                                        let n = to_len(read_varint(r)?)?;
                                        read_utf8(r, n)?
                                    };
                                    let f1_amount = read_lf32(r)?;
                                    let f1_operation = read_li32(r)?;
                                    let f1_operand = read_li32(r)?;
                                    let f1_serializable = read_bool(r)?;
                                    types::PlayerAttributesItemModifiersItem {
                                        id: f1_id,
                                        name: f1_name,
                                        amount: f1_amount,
                                        operation: f1_operation,
                                        operand: f1_operand,
                                        serializable: f1_serializable,
                                    }
                                });
                            }
                            v
                        };
                        types::PlayerAttributesItem {
                            min: f_min,
                            max: f_max,
                            current: f_current,
                            default_min: f_default_min,
                            default_max: f_default_max,
                            default: f_default,
                            name: f_name,
                            modifiers: f_modifiers,
                        }
                    });
                }
                v
            })
        })()
        .map_err(|e| e.at("UpdateAttributes.attributes"))?;
        let f_tick = (|| -> Result<_> { Ok(read_varint64(r)?) })()
            .map_err(|e| e.at("UpdateAttributes.tick"))?;
        Ok(Self {
            runtime_entity_id: f_runtime_entity_id,
            attributes: f_attributes,
            tick: f_tick,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_varint64(w, self.runtime_entity_id);
        write_varint(w, self.attributes.len() as u32);
        for x0 in self.attributes.iter() {
            {
                let x1 = x0;
                write_lf32(w, x1.min);
                write_lf32(w, x1.max);
                write_lf32(w, x1.current);
                write_lf32(w, x1.default_min);
                write_lf32(w, x1.default_max);
                write_lf32(w, x1.default);
                {
                    let b = x1.name.as_bytes();
                    write_varint(w, b.len() as u32);
                    write_slice(w, b);
                }
                write_varint(w, x1.modifiers.len() as u32);
                for x2 in x1.modifiers.iter() {
                    {
                        let x3 = x2;
                        {
                            let b = x3.id.as_bytes();
                            write_varint(w, b.len() as u32);
                            write_slice(w, b);
                        }
                        {
                            let b = x3.name.as_bytes();
                            write_varint(w, b.len() as u32);
                            write_slice(w, b);
                        }
                        write_lf32(w, x3.amount);
                        write_li32(w, x3.operation);
                        write_li32(w, x3.operand);
                        write_bool(w, x3.serializable);
                    }
                }
            }
        }
        write_varint64(w, self.tick);
    }
}
